From e3724e606788ff200fc1f07113fe68d24d51d823 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 19:51:20 +0100
Subject: [PATCH] libnotificationmanager: Replace older identical notifications

When an app sent the same notification again, such as a connection that
drops every night, each copy stacked up in the popups and the history. A
new notification identical to older ones now revokes and replaces them.

BUG: 491181
---
 libnotificationmanager/notificationsmodel.cpp | 14 ++++++++++++++
 1 file changed, 14 insertions(+)

diff --git a/libnotificationmanager/notificationsmodel.cpp b/libnotificationmanager/notificationsmodel.cpp
index 21a1fceff4..74daccb57a 100644
--- a/libnotificationmanager/notificationsmodel.cpp
+++ b/libnotificationmanager/notificationsmodel.cpp
@@ -27,6 +27,20 @@ NotificationsModel::Ptr NotificationsModel::createNotificationsModel()
 NotificationsModel::NotificationsModel()
 {
     connect(&Server::self(), &Server::notificationAdded, this, [this](const Notification &notification) {
+        // A new notification identical to older ones replaces them instead of stacking up
+        QList<uint> identicalIds;
+        for (const Notification &existing : notifications()) {
+            if (existing.applicationName() == notification.applicationName() && existing.desktopEntry() == notification.desktopEntry()
+                && existing.notifyRcName() == notification.notifyRcName() && existing.eventId() == notification.eventId()
+                && existing.summary() == notification.summary() && existing.body() == notification.body() && existing.icon() == notification.icon()
+                && existing.urls() == notification.urls() && existing.actionNames() == notification.actionNames()) {
+                identicalIds.append(existing.id());
+            }
+        }
+        for (const uint id : std::as_const(identicalIds)) {
+            Server::self().closeNotification(id, Server::CloseReason::Revoked);
+        }
+
         onNotificationAdded(notification);
     });
     connect(&Server::self(), &Server::notificationReplaced, this, [this](uint replacedId, const Notification &notification) {
